protected void lbtEdit_Click(object sender, EventArgs e)
{
    LinkButton lbt = sender as LinkButton;
    uEdit.Clear();
    if (lbt.CommandArgument != "")
    {
        uEdit.LoadInfo(Convert.ToInt64(lbt.CommandArgument));
        uEdit.ShowPopup();
    }
    else // tạo mới
    {
        int intIndex = Convert.ToInt32(lbt.ToolTip);
        RepeaterItem rptItem = rptList.Items[intIndex];

        HiddenField hidTeacherIDOfSchedule = rptItem.FindControl("hidTeacherIDOfSchedule") as HiddenField;
        HiddenField hidTheoryQuantity = rptItem.FindControl("hidTheoryQuantity") as HiddenField;
        HiddenField hidPracticeQuantity = rptItem.FindControl("hidPracticeQuantity") as HiddenField;
        HiddenField hidTestQuantity = rptItem.FindControl("hidTestQuantity") as HiddenField;
        HiddenField hidSession = rptItem.FindControl("hidSession") as HiddenField;

        uEdit.ClassSubjectID = this.ClassSubjectID;
        uEdit.Date = Convert.ToDateTime(lbt.CommandName);
        uEdit.SessionID = Convert.ToInt32(hidSession.Value);
        uEdit.TeacherID = hidTeacherIDOfSchedule.Value; // giáo viên của lịch                

        if (hidTheoryQuantity.Value != "")
            uEdit.TheoryQuantity = Convert.ToInt32(hidTheoryQuantity.Value);
        if (hidPracticeQuantity.Value != "")
            uEdit.PracticeQuantity = Convert.ToInt32(hidPracticeQuantity.Value);
        if (hidTestQuantity.Value != "")
            uEdit.TestQuantity = Convert.ToInt32(hidTestQuantity.Value);

        uEdit.ShowPopup();
    }
}

