private int? ToQuantity(string value)
{
    if (value == null || value.Trim() == "")
        return null;
    decimal quantity;
    string text = value.Trim().Replace(",", ".");
    if (!decimal.TryParse(text, System.Globalization.NumberStyles.Number, System.Globalization.CultureInfo.InvariantCulture, out quantity))
        return null;
    return Convert.ToInt32(quantity);
}

